import { Fragment, type ReactNode } from 'react'
import S from './strings.json'

// Strings come from dashboard/lang/en.php (generated by scripts/sync-live-api.sh).
// A few carry simple markup; Rich renders only strong/b/em/code/br and https
// links, everything else is shown as text.
const STR = S as Record<string, string>
export const t = (k: string, ...args: string[]) => {
  let s = STR[k] ?? k
  args.forEach((a) => { s = s.replace('%s', a) })
  return s
}
export const plain = (k: string) => t(k).replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim()

function walk(n: Node, key: string): ReactNode {
  if (n.nodeType === 3) return n.textContent
  if (n.nodeType !== 1) return null
  const el = n as Element, kids = Array.from(el.childNodes).map((c, i) => walk(c, `${key}.${i}`))
  switch (el.tagName.toLowerCase()) {
    case 'strong': case 'b': return <strong key={key}>{kids}</strong>
    case 'em': case 'i': return <em key={key}>{kids}</em>
    case 'code': return <code key={key}>{kids}</code>
    case 'br': return <br key={key} />
    case 'a': { const h = el.getAttribute('href') || ''; return /^https:\/\//.test(h) ? <a key={key} href={h} target="_blank" rel="noopener noreferrer">{kids}</a> : <Fragment key={key}>{kids}</Fragment> }
    default: return <Fragment key={key}>{kids}</Fragment>
  }
}
export function Rich({ k, s }: { k?: string; s?: string }) {
  const doc = new DOMParser().parseFromString(`<body>${s ?? t(k || '')}</body>`, 'text/html')
  return <>{Array.from(doc.body.childNodes).map((c, i) => walk(c, String(i)))}</>
}
